// Android Java/Kotlin BroadcastReceiver for Zebra DataWedge Intent
private val barcodeReceiver = object : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action == "com.uemlabs.ACTION_BARCODE") {
            val barcode = intent.getStringExtra("com.symbol.datawedge.data_string")
            val symbology = intent.getStringExtra("com.symbol.datawedge.label_type")
            Log.d("SCANNER", "Scanned: $barcode ($symbology)")
        }
    }
}

